{
  "IP": "neorv32_sysinfo",
  "Conceptual Assets": [
    {
      "Concept ID": "C1",
      "Concept Name": "Writable system-information word",
      "Unit": "neorv32_sysinfo",
      "Information": "A system-information value initialized to the configured clock frequency and writable by a bus access, on which software can depend when reading the IP's reported system information. It enters through a bus write and leaves through the system-information read response.",
      "Rubric": {
        "Confidentiality": "no",
        "Integrity": "yes",
        "Availability": "no",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "Integrity is at risk because the value is reset and stored at line 92 but can be overwritten by bus request data at line 95, allowing a write to falsify the value returned at line 168.",
      "Objectives At Risk": [
        "I"
      ],
      "Attack": "An unprivileged bus master could issue a write selecting this word and replace the reported system information, causing software to rely on a false setting (line 95).",
      "Enters Through": [
        "bus_req_i.data"
      ],
      "Leaves Through": [
        "bus_rsp_o.data"
      ],
      "Entry Lines": [
        95
      ],
      "Held Lines": [
        92,
        95
      ],
      "Exit Lines": [
        168
      ]
    }
  ],
  "Not Kept": [
    {
      "Candidate Name": "Build-time hardware configuration metadata",
      "Candidate Unit": "neorv32_sysinfo",
      "Merged Into": "",
      "Why Not Kept": "The feature, memory, cache, boot and peripheral metadata is fixed by generics and constants at build time (lines 102-150), so the build-time-values rule excludes it as a conceptual asset."
    },
    {
      "Candidate Name": "Bus access command",
      "Candidate Unit": "neorv32_sysinfo",
      "Merged Into": "",
      "Why Not Kept": "The request strobe, direction and address only select and qualify accesses to the information words (lines 94 and 161-162), so they are access command fields rather than information of their own."
    },
    {
      "Candidate Name": "Buffered access address",
      "Candidate Unit": "neorv32_sysinfo",
      "Merged Into": "",
      "Why Not Kept": "The buffered address only selects which information word is returned during the access (lines 162 and 168), making it a held address copy rather than a separate conceptual asset."
    },
    {
      "Candidate Name": "Bus response handshake and error status",
      "Candidate Unit": "neorv32_sysinfo",
      "Merged Into": "",
      "Why Not Kept": "The acknowledge repeats the request strobe and the error flag is tied to a constant (lines 160 and 169-170), so the handshake-copy and constant-status rules exclude them."
    },
    {
      "Candidate Name": "Clock, reset and access timing state",
      "Candidate Unit": "neorv32_sysinfo",
      "Merged Into": "",
      "Why Not Kept": "The clock and reset only time or initialize assignments, while the access buffering only retimes the transaction (lines 89-97 and 154-164), so the clock/reset and pacing rules exclude this state."
    }
  ],
  "Notes": []
}
